-- PostgreSQL 15+; synthetic POS data only.
CREATE SCHEMA IF NOT EXISTS pos_demo;
CREATE TABLE IF NOT EXISTS pos_demo.products(product_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sku TEXT NOT NULL UNIQUE,label TEXT NOT NULL,unit_price NUMERIC(18,2) NOT NULL CHECK(unit_price>=0),currency CHAR(3) NOT NULL DEFAULT 'UGX',active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS pos_demo.sales(sale_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,receipt_ref TEXT NOT NULL UNIQUE,terminal_ref TEXT NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),currency CHAR(3) NOT NULL,status TEXT NOT NULL DEFAULT 'posted' CHECK(status IN('posted','voided','partially_returned','returned')),idempotency_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS pos_demo.sale_lines(sale_line_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sale_id BIGINT NOT NULL REFERENCES pos_demo.sales(sale_id) ON DELETE RESTRICT,product_id BIGINT NOT NULL REFERENCES pos_demo.products(product_id) ON DELETE RESTRICT,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price NUMERIC(18,2) NOT NULL CHECK(unit_price>=0),line_total NUMERIC(18,2) GENERATED ALWAYS AS(quantity*unit_price) STORED,UNIQUE(sale_id,product_id));
CREATE TABLE IF NOT EXISTS pos_demo.stock_events(stock_event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES pos_demo.products(product_id) ON DELETE RESTRICT,quantity_delta INTEGER NOT NULL CHECK(quantity_delta<>0),reason TEXT NOT NULL CHECK(reason IN('opening','sale','return','adjustment')),source_ref TEXT NOT NULL UNIQUE,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pos_demo.returns(return_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,return_ref TEXT NOT NULL UNIQUE,sale_line_id BIGINT NOT NULL REFERENCES pos_demo.sale_lines(sale_line_id) ON DELETE RESTRICT,quantity INTEGER NOT NULL CHECK(quantity>0),reason TEXT NOT NULL CHECK(reason IN('damaged','wrong_item','customer_return','other')),approved_by_ref TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_pos_sales_time ON pos_demo.sales(occurred_at DESC,status);
CREATE INDEX IF NOT EXISTS ix_pos_sale_lines_product ON pos_demo.sale_lines(product_id,sale_id);
CREATE INDEX IF NOT EXISTS ix_pos_stock_history ON pos_demo.stock_events(product_id,happened_at DESC,stock_event_id DESC);